import itertools
import networkx as nx

def is_close(r, s):
    for x, y in zip(r, s):
        if abs(x - y) >= 2:
            return False
    return True

def solve(m):
    perms = list(itertools.permutations(range(1, m + 1)))
    n = len(perms)
    G = nx.Graph()
    G.add_nodes_from(range(n))
    for i in range(n):
        for j in range(i + 1, n):
            if is_close(perms[i], perms[j]):
                G.add_edge(i, j)

    comp_G = nx.complement(G)
    clique, weight = nx.clique.max_weight_clique(comp_G, weight=None)
    return len(clique)

print(f"m=2: {solve(2)}")
print(f"m=4: {solve(4)}")

